window.TEACH_SLIDES['7-16'] = [{"k": "title", "html": "<p class=\"ts-kicker\">ថ្នាក់ទី ៧ · មេរៀនទី ១៦</p><h1>បរិមាត្រនិងផ្ទៃក្រឡាពហុកោណ</h1><p class=\"ts-sub\">៣ ផ្នែក</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៦</p><h2>គោលបំណង</h2><ol class=\"ts-bullets\"><li>គណនាបរិមាត្រចតុកោណកែង ការ៉េ និងត្រីកោណ</li><li>បង្ហាញសញ្ញាណផ្ទៃនិងផ្ទៃក្រឡា</li><li>រកផ្ទៃក្រឡានៃចតុកោណកែង ការ៉េ និងត្រីកោណ</li><li>ដោះស្រាយចំណោទ ។</li></ol>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>1. សញ្ញាណបរិមាត្រ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.1. សញ្ញាណទូទៅនៃបរិមាត្រ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>រកប្រវែងខ្សែកាច់នៃរូបខាងក្រោម ។</p><p>\\[AE=AB+BC+CD+DE\\] ហៅថា <b>ប្រវែងខ្សែកាច់</b> ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>រកប្រវែងជុំវិញពហុកោណ \\(ABCDEFGH\\) ។</p><p>\\[P=AB+BC+CD+DE+EF+FG+GH+HA\\] ហៅថា <b>បរិមាត្រ</b> ពហុកោណ \\(ABCDEFGH\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.1. សញ្ញាណទូទៅនៃបរិមាត្រ</p><h2>ជាទូទៅ</h2><p>បរិមាត្រពហុកោណ គឺជាប្រវែងខ្សែកាច់បិទជិតដែលកំណត់ពហុកោណនោះ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.1. សញ្ញាណទូទៅនៃបរិមាត្រ</p><h2>លំហាត់គំរូ</h2><p>គណនាបរិមាត្រពហុកោណរូបខាងក្រោម ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.1. សញ្ញាណទូទៅនៃបរិមាត្រ</p><h2>ដំណោះស្រាយ</h2><p>បរិមាត្រពហុកោណ ៖ \\[\\begin{aligned}\nP &amp;= 12~\\text{cm}+7~\\text{cm}+5~\\text{cm}+10~\\text{cm}+14~\\text{cm}+23~\\text{cm} \\\\\n &amp;= 71~\\text{cm}\n\\end{aligned}\\] ដូច្នេះបរិមាត្រពហុកោណគឺ \\(P=71~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.1. សញ្ញាណទូទៅនៃបរិមាត្រ</p><h2>ប្រតិបត្តិ</h2><p>រកបរិមាត្រពហុកោណខាងក្រោម ៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.1. សញ្ញាណទូទៅនៃបរិមាត្រ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ពហុកោណមាន \\(8\\) ជ្រុងស្មើគ្នា (មានសញ្ញាដូចគ្នា) ជ្រុងមួយ \\(53.4~\\text{cm}\\) ៖ \\[P=8\\times53.4=427.2~\\text{cm}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ផ្កាយមាន \\(8\\) ជ្រុង ដែលជ្រុងចំនួន \\(4\\) ប្រវែង \\(50.8~\\text{cm}\\) និងជ្រុងចំនួន \\(4\\) ប្រវែង \\(73~\\text{cm}\\) ៖ \\[\\begin{aligned}\n    P &amp;= 4\\times50.8+4\\times73 \\\\\n     &amp;= 203.2+292 \\\\\n     &amp;= 495.2~\\text{cm}\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តាមសញ្ញាដូចគ្នា ជ្រុង \\(54.3~\\text{cm}\\) មាន \\(2\\) ជ្រុង ជ្រុង \\(6~\\text{cm}\\) មាន \\(4\\) ជ្រុង ជ្រុង \\(6.7~\\text{cm}\\) មាន \\(4\\) ជ្រុង និងជ្រុង \\(12~\\text{cm}\\) មាន \\(2\\) ជ្រុង ៖ \\[\\begin{aligned}\n    P &amp;= 2\\times54.3+4\\times6+4\\times6.7+2\\times12 \\\\\n     &amp;= 108.6+24+26.8+24 \\\\\n     &amp;= 183.4~\\text{cm}\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ក. \\(427.2~\\text{cm}\\) ខ. \\(495.2~\\text{cm}\\) គ. \\(183.4~\\text{cm}\\) ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.2. បរិមាត្រចតុកោណកែង</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាបរិមាត្រចតុកោណកែងក្នុងរូបខាងក្រោម ។</p><p>បរិមាត្រចតុកោណកែងគឺ \\[\\begin{aligned}\nP &amp;= 73~\\text{dm}+119~\\text{dm}+73~\\text{dm}+119~\\text{dm} \\\\\n &amp;= 384~\\text{dm}\n\\end{aligned}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាបរិមាត្រចតុកោណកែងមានវិមាត្រ \\(a\\) និង \\(b\\) ។</p><p>បរិមាត្រចតុកោណកែង \\(ABCD\\) គឺ \\[P=a+b+a+b=2a+2b=2(a+b)\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.2. បរិមាត្រចតុកោណកែង</p><h2>រូបមន្ត</h2><p>បរិមាត្រចតុកោណកែង គឺជា \\(P=2(a+b)\\) ដែល \\(a\\) ជាប្រវែងទទឹង និង \\(b\\) ជាប្រវែងបណ្តោយ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.2. បរិមាត្រចតុកោណកែង</p><h2>លំហាត់គំរូ</h2><p>ចម្ការស្វាយមួយរាងចតុកោណកែងមានបរិមាត្រ \\(424~\\text{m}\\) និងទទឹងស្មើ \\(15.50~\\text{m}\\) ។ គណនាបណ្តោយចម្ការស្វាយនោះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.2. បរិមាត្រចតុកោណកែង</p><h2>ដំណោះស្រាយ</h2><p>បរិមាត្រចម្ការស្វាយ \\(P=2(a+b)\\) នាំឱ្យ \\(b=\\dfrac{P}{2}-a\\) ។ ដោយ \\(P=424~\\text{m}\\), \\(a=15.50~\\text{m}\\) គេបាន \\[\\begin{aligned}\nb &amp;= \\frac{424}{2}-15.50 \\\\\n &amp;= 212-15.50 \\\\\n &amp;= 196.5\n\\end{aligned}\\] ដូច្នេះបណ្តោយចម្ការស្វាយគឺ \\(b=196.5~\\text{m}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.2. បរិមាត្រចតុកោណកែង</p><h2>ប្រតិបត្តិ</h2><p>ដីស្រែមួយរាងចតុកោណកែងមានវិមាត្រស្មើនឹង \\(55~\\text{m}\\) និង \\(107~\\text{m}\\) ។ គណនាបរិមាត្រដីស្រែនោះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.2. បរិមាត្រចតុកោណកែង</p><h2>ចម្លើយ</h2><p>\\[\\begin{aligned}\nP &amp;= 2(55+107) \\\\\n &amp;= 2\\times162 \\\\\n &amp;= 324~\\text{m}\n\\end{aligned}\\] ដូចនេះ \\(324~\\text{m}\\) ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាបរិមាត្រការ៉េមានរង្វាស់ជ្រុងស្មើនឹង \\(27~\\text{cm}\\) ។</p><p>បរិមាត្រការ៉េគឺ \\[\\begin{aligned}\nP &amp;= 27~\\text{cm}+27~\\text{cm}+27~\\text{cm}+27~\\text{cm} \\\\\n &amp;= 4\\times27~\\text{cm} \\\\\n &amp;= 108~\\text{cm}\n\\end{aligned}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាបរិមាត្រការ៉េ តាមរូបខាងក្រោម ៖</p><p>បរិមាត្រការ៉េគឺ \\(P=a+a+a+a=4a\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>រូបមន្ត</h2><p>បរិមាត្រការ៉េ គឺ \\(P=4a\\) ដែល \\(a\\) ជាជ្រុងការ៉េ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>លំហាត់គំរូ 1</h2><p>ស្រះចិញ្ចឹមត្រីមួយរាងការ៉េមានរង្វាស់ជ្រុងស្មើនឹង \\(18~\\text{m}\\) ។ គណនាបរិមាត្រស្រះនោះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\nP &amp;= 4\\times18~\\text{m} \\\\\n &amp;= 72~\\text{m}\n\\end{aligned}\\] ដូច្នេះ \\(P=72~\\text{m}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>លំហាត់គំរូ 2</h2><p>ចម្ការពោតមួយរាងការ៉េ ។ គេធ្វើរបងព័ទ្ធខ្សែលួស \\(3\\) ជុំអស់លួសប្រវែង \\(864~\\text{m}\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាបរិមាត្រចម្ការពោត</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គណនាប្រវែងជ្រុងចម្ការពោត ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>ដំណោះស្រាយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បរិមាត្រចម្ការពោតស្មើនឹងប្រវែងខ្សែលួស \\(1\\) ជុំ ៖ \\[P=\\frac{864}{3}=288~\\text{m}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ប្រវែងជ្រុងចម្ការពោត ៖ \\[a=\\frac{288~\\text{m}}{4}=72~\\text{m}\\]</div></li></ul><p>ដូច្នេះបរិមាត្រចម្ការពោត \\(P=288~\\text{m}\\) និងជ្រុងចម្ការពោត \\(a=72~\\text{m}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>ប្រតិបត្តិ</h2><p>សុខាមានក្រដាសមួយសន្លឹកដូចរូបខាងក្រោម ។ តើសុខាត្រូវកាត់ក្រដាសតាមរបៀបណាដើម្បីផ្គុំបានជាការ៉េ ? គណនាបរិមាត្រនៃការ៉េដែលផ្គុំបាន ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.3. បរិមាត្រការ៉េ</p><h2>ចម្លើយ</h2><p>ក្រដាសមានផ្ទៃក្រឡា \\(9\\times4=36~\\text{cm}^2\\) ។ ការ៉េដែលផ្គុំបានមានផ្ទៃក្រឡា \\(36~\\text{cm}^2\\) ដូចនេះជ្រុងរបស់វា \\(6~\\text{cm}\\) ។</p><p>កាត់ក្រដាសជាពីរផ្នែកតាមជណ្តើរ (\\(3\\) ជាន់ ដែលជាន់នីមួយៗទទឹង \\(3~\\text{cm}\\) និងកម្ពស់ \\(2~\\text{cm}\\)) ដូចរូប រួចរំកិលផ្នែកខាងស្តាំឡើងលើ \\(2~\\text{cm}\\) និងទៅឆ្វេង \\(3~\\text{cm}\\) ។</p><p>\\[P=4\\times6=24~\\text{cm}\\] ដូចនេះ ផ្គុំជាការ៉េដែលមានជ្រុង \\(6~\\text{cm}\\) និង \\(P=24~\\text{cm}\\) ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.4. បរិមាត្រត្រីកោណ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាបរិមាត្រត្រីកោណមានរង្វាស់ជ្រុងដូចក្នុងរូបខាងក្រោម ។</p><p>ប្រវែងបរិមាត្រត្រីកោណគឺ \\[P_{\\Delta ABC}=14~\\text{cm}+12~\\text{cm}+25~\\text{cm}=51~\\text{cm}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាបរិមាត្រត្រីកោណដែលមានរង្វាស់ជ្រុងដូចរូបខាងក្រោម ។</p><p>ប្រវែងបរិមាត្រត្រីកោណគឺ \\(P_{\\Delta ABC}=a+b+c\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.4. បរិមាត្រត្រីកោណ</p><h2>រូបមន្ត</h2><p>បរិមាត្រត្រីកោណមានរង្វាស់ជ្រុង \\(a,b,c\\) គឺ \\(P=a+b+c\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.4. បរិមាត្រត្រីកោណ</p><h2>លំហាត់គំរូ</h2><p>គណនាបរិមាត្រត្រីកោណសមបាត \\(ABC\\) ដោយស្គាល់រង្វាស់ជ្រុង \\(AB=AC=27~\\text{cm}\\), \\(BC=21~\\text{cm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.4. បរិមាត្រត្រីកោណ</p><h2>ដំណោះស្រាយ</h2><p>បរិមាត្រត្រីកោណសមបាត \\(ABC\\) ៖ \\[\\begin{aligned}\nP &amp;= 2\\times AB+BC \\\\\n &amp;= 2\\times27~\\text{cm}+21~\\text{cm} \\\\\n &amp;= 75~\\text{cm}\n\\end{aligned}\\] ដូច្នេះ \\(P=75~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.4. បរិមាត្រត្រីកោណ</p><h2>ប្រតិបត្តិ</h2><p>គណនាបរិមាត្រត្រីកោណ \\(ABC\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. សញ្ញាណបរិមាត្រ · 1.4. បរិមាត្រត្រីកោណ</p><h2>ចម្លើយ</h2><p>\\[\\begin{aligned}\nP &amp;= 13+17+19 \\\\\n &amp;= 49~\\text{dm}\n\\end{aligned}\\] ដូចនេះ \\(49~\\text{dm}\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>2. ផ្ទៃក្រឡាពហុកោណ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.1. សញ្ញាណផ្ទៃនិងផ្ទៃក្រឡា</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>ខ្សែកោង \\(L\\) បិទជិតបង្កើតបានផ្ទៃ \\(A\\) មួយ ។ ខ្សែកោង \\(L\\) ដែលត្រឡប់កាត់ខ្លួនឯង ពុំអាចកំណត់បានផ្ទៃតែមួយទេ ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>រូបទី \\(1\\) និងរូបទី \\(2\\) ជាផ្ទៃពីរមានរាងខុសគ្នា តែវាមាន \\(10\\) ការ៉ូដូចគ្នា ។ ដូច្នេះគេថាផ្ទៃរូបទី \\(1\\) និងផ្ទៃរូបទី \\(2\\) មានផ្ទៃក្រឡាស្មើគ្នា ។ បើគេយកការ៉េរូបទី \\(3\\) ជាការ៉េឯកតាផ្ទៃ នោះផ្ទៃក្រឡារូបទី \\(1\\) និងរូបទី \\(2\\) ស្មើនឹង \\(10\\) ឯកតាផ្ទៃដូចគ្នា ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.1. សញ្ញាណផ្ទៃនិងផ្ទៃក្រឡា</p><h2>ជាទូទៅ</h2><p>ផ្ទៃក្រឡា គឺជាចំនួននៃការ៉េឯកតាដែលនៅក្នុងផ្ទៃ ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.2. ឯកតាផ្ទៃក្រឡា</p><h2>ឧទាហរណ៍ 1</h2><p>បើគេវាស់ជ្រុងនៃបន្ទប់រៀនដោយយកឯកតាខ្នាតជាម៉ែត្រ (\\(\\text{m}\\)) នោះឯកតាផ្ទៃក្រឡាជាម៉ែត្រការ៉េ (\\(\\text{m}^2\\)) ។ ឯកតាផ្ទៃ មានដូចតារាងខាងក្រោម ៖</p><table class=\"ts-table\"><tr><td>ប្រវែងជ្រុង</td><td>\\(1~\\text{km}\\)</td><td>\\(1~\\text{hm}\\)</td><td>\\(1~\\text{dam}\\)</td><td>\\(1~\\text{m}\\)</td><td>\\(1~\\text{dm}\\)</td><td>\\(1~\\text{cm}\\)</td><td>\\(1~\\text{mm}\\)</td></tr><tr><td>ឯកតាផ្ទៃ</td><td>\\(1~\\text{km}^2\\)</td><td>\\(1~\\text{hm}^2\\)</td><td>\\(1~\\text{dam}^2\\)</td><td>\\(1~\\text{m}^2\\)</td><td>\\(1~\\text{dm}^2\\)</td><td>\\(1~\\text{cm}^2\\)</td><td>\\(1~\\text{mm}^2\\)</td></tr></table>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.2. ឯកតាផ្ទៃក្រឡា</p><h2>ជាទូទៅ</h2><p>ខ្នាតផ្ទៃក្រឡា គឺម៉ែត្រការ៉េ (\\(\\text{m}^2\\)) ។ ម៉ែត្រការ៉េ គឺជាផ្ទៃក្រឡានៃការ៉េដែលជ្រុងមានរង្វាស់ស្មើនឹង \\(1~\\text{m}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.2. ឯកតាផ្ទៃក្រឡា</p><h2>ចំណាំ</h2><p>ដើម្បីវាស់ដីស្រែចម្ការ គេច្រើនប្រើខ្នាតរង្វាស់ដូចជា សង់ទីអា (\\(\\text{ca}\\)), អា (\\(\\text{a}\\)), ហិកតា (\\(\\text{ha}\\)) ។ \\[1~\\text{ca}=1~\\text{m}^2, \\qquad 1~\\text{a}=1~\\text{dam}^2=100~\\text{m}^2, \\qquad 1~\\text{ha}=1~\\text{hm}^2=100~\\text{dam}^2=10~000~\\text{m}^2\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.2. ឯកតាផ្ទៃក្រឡា</p><h2>ប្រតិបត្តិ</h2><p>បំពេញចន្លោះខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(3~\\text{m}^2=\\dots\\dots~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(1~\\text{a}=\\dots\\dots~\\text{m}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(500~\\text{cm}^2=\\dots\\dots~\\text{m}^2\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.2. ឯកតាផ្ទៃក្រឡា</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(1~\\text{m}=100~\\text{cm}\\) ដូចនេះ \\(1~\\text{m}^2=100\\times100=10~000~\\text{cm}^2\\) ៖ \\[3~\\text{m}^2=3\\times10~000=30~000~\\text{cm}^2\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[1~\\text{a}=1~\\text{dam}^2=10\\times10=100~\\text{m}^2\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(1~\\text{cm}^2=\\dfrac{1}{10~000}~\\text{m}^2\\) ដូចនេះ ៖ \\[500~\\text{cm}^2=\\frac{500}{10~000}=0.05~\\text{m}^2\\]</div></li></ul>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាផ្ទៃក្រឡាចតុកោណកែងខាងក្រោម ។ ចតុកោណកែងមានជួរឈរ \\(4\\) ការ៉ូ និងជួរដេក \\(7\\) ការ៉ូ ។</p><p>គេបាន \\[\\mathcal{A}=\\underbrace{4+4+4+4+4+4+4}_{7\\text{ ដង}}=7\\times4=28\\] ដូច្នេះផ្ទៃក្រឡាចតុកោណកែង គឺ \\(\\mathcal{A}=28\\) ការ៉ូ ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាផ្ទៃក្រឡាចតុកោណកែងដែលមានរង្វាស់ជ្រុង \\(a=6~\\text{cm}\\), \\(b=3~\\text{cm}\\) ។</p><p>ផ្ទៃក្រឡាចតុកោណកែង \\(=\\underbrace{6+6+6}_{3\\text{ ដង}}=18\\) ការ៉ូ ។ ឬ \\(3~\\text{cm}\\times6~\\text{cm}=18~\\text{cm}^2\\) គេបាន \\(\\mathcal{A}=a\\times b\\) ។</p><p>ដូច្នេះផ្ទៃក្រឡាចតុកោណកែង គឺ \\(\\mathcal{A}=18~\\text{cm}^2\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>រូបមន្ត</h2><p>ផ្ទៃក្រឡាចតុកោណកែង គឺ \\(\\mathcal{A}=a\\times b\\) ឬ បណ្តោយ \\(\\times\\) ទទឹង ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>លំហាត់គំរូ 1</h2><p>គណនាផ្ទៃក្រឡាចតុកោណកែង \\(ABCD\\) ដោយស្គាល់រង្វាស់ជ្រុង \\(AB=130~\\text{dm}\\) និង \\(AD=117~\\text{dm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>ដំណោះស្រាយ</h2><p>ផ្ទៃក្រឡាចតុកោណកែង \\(ABCD\\) ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= AB\\times AD \\\\\n &amp;= 130~\\text{dm}\\times117~\\text{dm} \\\\\n &amp;= 15~210~\\text{dm}^2\n\\end{aligned}\\] ដូច្នេះ \\(\\mathcal{A}=15~210~\\text{dm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>លំហាត់គំរូ 2</h2><p>គណនាជ្រុងចតុកោណកែង \\(ABCD\\) ដោយស្គាល់ \\(AB=207~\\text{cm}\\) និង \\(\\mathcal{A}=14~076~\\text{cm}^2\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>ដំណោះស្រាយ</h2><p>តាង \\(x\\) ជាជ្រុងចតុកោណកែង \\(ABCD\\) ដែលត្រូវរក ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= x\\times AB \\\\\nx &amp;= \\frac{\\mathcal{A}}{AB} \\\\\n &amp;= \\frac{14~076~\\text{cm}^2}{207~\\text{cm}} \\\\\n &amp;= 68~\\text{cm}\n\\end{aligned}\\] ដូច្នេះរង្វាស់ជ្រុងចតុកោណកែង គឺ \\(68~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>ប្រតិបត្តិ</h2><p>បំពេញចន្លោះក្នុងតារាងខាងក្រោម ៖</p><table class=\"ts-table\"><tr><td>ចតុកោណកែង</td><td>ជ្រុងទី \\(1\\)</td><td>ជ្រុងទី \\(2\\)</td><td>ផ្ទៃក្រឡា</td><td>បរិមាត្រ</td></tr><tr><td>ទី \\(1\\)</td><td>\\(25~\\text{cm}\\)</td><td>\\(\\dots\\dots~\\text{cm}\\)</td><td>\\(300~\\text{cm}^2\\)</td><td>\\(\\dots\\dots~\\text{cm}\\)</td></tr><tr><td>ទី \\(2\\)</td><td>\\(\\dots\\dots~\\text{dm}\\)</td><td>\\(24~\\text{dm}\\)</td><td>\\(\\dots\\dots~\\text{dm}^2\\)</td><td>\\(120~\\text{dm}\\)</td></tr><tr><td>ទី \\(3\\)</td><td>\\(10~\\text{m}\\)</td><td>\\(7~\\text{m}\\)</td><td>\\(70~\\text{m}^2\\)</td><td>\\(\\dots\\dots~\\text{m}\\)</td></tr><tr><td>ទី \\(4\\)</td><td>\\(1224~\\text{mm}\\)</td><td>\\(1222~\\text{mm}\\)</td><td>\\(\\dots\\dots~\\text{mm}^2\\)</td><td>\\(\\dots\\dots~\\text{mm}\\)</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.3. ផ្ទៃក្រឡាចតុកោណកែង</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ទី 1.</span><div>គេបាន ៖ \\[\\begin{aligned}\n    \\text{ជ្រុងទី }2 &amp;= \\frac{300}{25}=12~\\text{cm} \\\\\n    P &amp;= 2(25+12)=74~\\text{cm}\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ទី 2.</span><div>គេបាន ៖ \\[\\begin{aligned}\n    \\text{ជ្រុងទី }1 &amp;= \\frac{120}{2}-24=60-24=36~\\text{dm} \\\\\n    \\mathcal{A} &amp;= 36\\times24=864~\\text{dm}^2\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ទី 3.</span><div>គេបាន ៖ \\[P=2(10+7)=34~\\text{m}\\]</div></li><li class=\"lab\"><span class=\"lb\">ទី 4.</span><div>គេបាន ៖ \\[\\begin{aligned}\n    \\mathcal{A} &amp;= 1224\\times1222=1~495~728~\\text{mm}^2 \\\\\n    P &amp;= 2(1224+1222)=4~892~\\text{mm}\n    \\end{aligned}\\]</div></li></ul>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.4. ផ្ទៃក្រឡាការ៉េ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាផ្ទៃក្រឡាការ៉េខាងក្រោម ។</p><p>ការ៉េមានផ្ទៃក្រឡា \\(\\mathcal{A}=5\\times5=5^2=25\\) ។ ដូច្នេះការ៉េមានផ្ទៃក្រឡា \\(\\mathcal{A}=25\\) ឯកតាការ៉េ ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាផ្ទៃក្រឡាការ៉េ ដោយស្គាល់រង្វាស់ជ្រុង \\(a=6~\\text{cm}\\) ។</p><p>ផ្ទៃក្រឡាការ៉េ \\(=6\\times6=6^2=36\\) ឬ \\(\\mathcal{A}=a\\times a=a^2\\) ។ ដូច្នេះផ្ទៃក្រឡាការ៉េគឺ \\(\\mathcal{A}=36~\\text{cm}^2\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.4. ផ្ទៃក្រឡាការ៉េ</p><h2>រូបមន្ត</h2><p>ផ្ទៃក្រឡាការ៉េ គឺ \\(\\mathcal{A}=a^2\\) ដែល \\(a\\) ជាជ្រុង ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.4. ផ្ទៃក្រឡាការ៉េ</p><h2>លំហាត់គំរូ</h2><p>សូផាតធ្វើដំណើរទៅកម្សាន្តចម្ការកៅស៊ូមួយដែលមានរាងជាការ៉េ ពេលទៅដល់គាត់ឃើញស្លាកសញ្ញាមានមាត្រដ្ឋាន \\(\\dfrac{1}{100~000}\\) និងមានបរិមាត្រ \\(2.96~\\text{cm}\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាផ្ទៃក្រឡាដីពិតរបស់ចម្ការកៅស៊ូគិតជាហិកតា ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គណនាប្រវែងខ្សែលួស បើគេព័ទ្ធចម្ការនោះ \\(6\\) ជុំ ។</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>គណនាតម្លៃខ្សែលួស បើក្នុង \\(1~\\text{m}\\) ថ្លៃ \\(900~\\text{៛}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.4. ផ្ទៃក្រឡាការ៉េ</p><h2>ដំណោះស្រាយ</h2><p>មាត្រដ្ឋាន \\(1:100~000\\) មានន័យថាប្រវែង \\(1~\\text{cm}\\) នៅលើផែនទីតាងឱ្យ \\(100~000~\\text{cm}\\) ឬ \\(1~000~\\text{m}\\) នៅលើផ្ទៃដីពិត ។ បើ \\(a\\) ជាជ្រុងនៃចម្ការកៅស៊ូ គេបាន \\[\\begin{aligned}\nP &amp;= 4a=2.96\\times1~000~\\text{m}=2~960~\\text{m} \\\\\na &amp;= \\frac{2~960~\\text{m}}{4}=740~\\text{m}\n\\end{aligned}\\]</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ផ្ទៃក្រឡាចម្ការកៅស៊ូ ៖ \\[\\begin{aligned}\n    \\mathcal{A} &amp;= a^2=(740~\\text{m})^2 \\\\\n     &amp;= 547~600~\\text{m}^2 \\\\\n     &amp;= 54.76~\\text{ha}\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ប្រវែងខ្សែលួស ៖ \\[L=2~960~\\text{m}\\times6=17~760~\\text{m}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តម្លៃខ្សែលួសទាំងអស់ ៖ \\[M=900~\\text{៛}\\times17~760=15~984~000~\\text{៛}\\]</div></li></ul><p>ដូច្នេះ \\(\\mathcal{A}=54.76~\\text{ha}\\), \\(L=17~760~\\text{m}\\), \\(M=15~984~000~\\text{៛}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.4. ផ្ទៃក្រឡាការ៉េ</p><h2>ប្រតិបត្តិ</h2><p>សង់ការ៉េមួយមានបរិមាត្រ \\(172~\\text{cm}\\) ។ គណនាផ្ទៃក្រឡាការ៉េនេះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.4. ផ្ទៃក្រឡាការ៉េ</p><h2>ចម្លើយ</h2><p>\\[\\begin{aligned}\na &amp;= \\frac{172}{4}=43~\\text{cm} \\\\\n\\mathcal{A} &amp;= a^2=43^2=1~849~\\text{cm}^2\n\\end{aligned}\\] ដូចនេះ \\(1~849~\\text{cm}^2\\) ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាផ្ទៃក្រឡាត្រីកោណ រូបទី \\(1\\) ។</p><p>តាមរូបត្រីកោណ គេរាប់ឃើញមានការ៉ូពេញចំនួន \\(12\\) ឯកតា និងការ៉ូមិនពេញចំនួន \\(8\\) ឯកតា គឺមាន \\(\\dfrac{8}{2}=4\\) ការ៉ូពេញ ។ ដូច្នេះ ៖ \\[\\mathcal{A}_1=12+4=16 \\text{ ការ៉ូ}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាផ្ទៃក្រឡាត្រីកោណ \\(ABC\\) ។</p><p>ផ្ទៃក្រឡាចតុកោណកែង \\(ABCD\\) ៖ \\[\\mathcal{A}_{ABCD}=b\\times h=4\\times7=28 \\text{ ការ៉ូ}\\] ផ្ទៃក្រឡាត្រីកោណស្មើពាក់កណ្តាលនៃ \\(\\mathcal{A}_{ABCD}\\) ៖ \\[\\mathcal{A}_{ABC}=\\frac{\\mathcal{A}_{ABCD}}{2}=\\frac{1}{2}\\times b\\times h=\\frac{1}{2}\\times4\\times7=14 \\text{ ការ៉ូ}\\] គេបាន \\(\\mathcal{A}_{ABC}=\\dfrac{1}{2}bh\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>រូបមន្ត</h2><p>ផ្ទៃក្រឡាត្រីកោណ គឺ \\(\\mathcal{A}=\\dfrac{1}{2}bh\\) ដែល \\(b\\) ជាបាតនិង \\(h\\) ជាកម្ពស់ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>លំហាត់គំរូ 1</h2><p>គណនាផ្ទៃក្រឡាត្រីកោណសមបាតខាងក្រោម ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\n\\mathcal{A}_{\\Delta ABC} &amp;= \\frac{1}{2}BC\\times AH \\\\\n &amp;= \\frac{1}{2}\\times24~\\text{cm}\\times17~\\text{cm} \\\\\n &amp;= 204~\\text{cm}^2\n\\end{aligned}\\] ដូច្នេះ \\(\\mathcal{A}=204~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>លំហាត់គំរូ 2</h2><p>គណនាកម្ពស់ត្រីកោណមួយដោយស្គាល់ផ្ទៃក្រឡា \\(\\mathcal{A}=132~\\text{dm}^2\\) និងបាត \\(a=34~\\text{dm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>ដំណោះស្រាយ</h2><p>តាមរូបមន្តគេបាន \\(\\mathcal{A}=\\dfrac{1}{2}a\\times h\\) នាំឱ្យ \\(h=\\dfrac{2\\mathcal{A}}{a}\\) ។ \\[\\begin{aligned}\nh &amp;= \\frac{2\\times132~\\text{dm}^2}{34~\\text{dm}} \\\\\n &amp;= \\frac{264}{34} \\\\\n &amp;= 7.76~\\text{dm}\n\\end{aligned}\\] ដូច្នេះ \\(h=7.76~\\text{dm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>ប្រតិបត្តិ</h2><p>បំពេញតារាងខាងក្រោម ៖</p><table class=\"ts-table\"><tr><td>ត្រីកោណ</td><td>ជ្រុងទី \\(1\\)</td><td>ជ្រុងទី \\(2\\)</td><td>បាត</td><td>កម្ពស់</td><td>ផ្ទៃក្រឡា</td><td>បរិមាត្រ</td></tr><tr><td>ទី \\(1\\)</td><td>\\(10~\\text{cm}\\)</td><td>(1) \\(\\dots\\)</td><td>\\(16~\\text{cm}\\)</td><td>\\(8~\\text{cm}\\)</td><td>(2) \\(\\dots\\)</td><td>\\(40~\\text{cm}\\)</td></tr><tr><td>ទី \\(2\\)</td><td>\\(20~\\text{cm}\\)</td><td>\\(20~\\text{cm}\\)</td><td>(3) \\(\\dots\\)</td><td>(4) \\(\\dots\\)</td><td>\\(192~\\text{cm}^2\\)</td><td>\\(72~\\text{cm}\\)</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ផ្ទៃក្រឡាពហុកោណ · 2.5. ផ្ទៃក្រឡាត្រីកោណ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">(1)</span><div>ជ្រុងទី \\(2=P-\\) ជ្រុងទី \\(1-\\) បាត ៖ \\[40-10-16=14~\\text{cm}\\]</div></li><li class=\"lab\"><span class=\"lb\">(2)</span><div>គេបាន ៖ \\[\\mathcal{A}=\\frac{1}{2}\\times16\\times8=64~\\text{cm}^2\\]</div></li><li class=\"lab\"><span class=\"lb\">(3)</span><div>ត្រីកោណទី \\(2\\) មានបាត \\(=P-20-20\\) ៖ \\[72-20-20=32~\\text{cm}\\]</div></li><li class=\"lab\"><span class=\"lb\">(4)</span><div>គេបាន ៖ \\[\\begin{aligned}\n    \\mathcal{A} &amp;= \\frac{1}{2}\\times32\\times h=192 \\\\\n    h &amp;= \\frac{2\\times192}{32}=12~\\text{cm}\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ (1) \\(14~\\text{cm}\\) (2) \\(64~\\text{cm}^2\\) (3) \\(32~\\text{cm}\\) (4) \\(12~\\text{cm}\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>3. ចំណោទ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">3. ចំណោទ</p><h2>ឧទាហរណ៍</h2><p>ចម្ការកប្បាសមួយមានរាងចតុកោណកែងដោយស្គាល់បរិមាត្រ \\(520~\\text{m}\\) ហើយទទឹងខ្លីជាងបណ្តោយ \\(25~\\text{m}\\) ។ រកផ្ទៃក្រឡាចម្ការកប្បាស ។</p><p>តាង \\(x\\) ជាទទឹងចម្ការ គេបានបណ្តោយចម្ការគឺ \\(x+25\\) ។ \\[\\begin{aligned}\n\\text{កន្លះបរិមាត្រចម្ការ} &amp;= \\frac{520~\\text{m}}{2}=260~\\text{m} \\\\\n2x+25 &amp;= 260 \\\\\nx &amp;= \\frac{260~\\text{m}-25~\\text{m}}{2}=117.5~\\text{m}\n\\end{aligned}\\] \\[\\text{បណ្តោយចម្ការ}=117.5~\\text{m}+25~\\text{m}=142.5~\\text{m}\\] \\[\\begin{aligned}\n\\mathcal{A} &amp;= 117.5~\\text{m}\\times142.5~\\text{m} \\\\\n &amp;= 16~743.75~\\text{m}^2\n\\end{aligned}\\] ដូច្នេះផ្ទៃក្រឡាចម្ការកប្បាស \\(\\mathcal{A}=16~743.75~\\text{m}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ចំណោទ</p><h2>លំហាត់គំរូ</h2><p>គណនាផ្ទៃក្រឡារូបខាងក្រោម ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ចំណោទ</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\n\\mathcal{A} &amp;= \\mathcal{A}_1+\\mathcal{A}_2 \\\\\n\\mathcal{A}_1 &amp;= 15~\\text{cm}\\times22~\\text{cm}=330~\\text{cm}^2 \\\\\n\\mathcal{A}_2 &amp;= \\frac{1}{2}\\times18~\\text{cm}\\times22~\\text{cm}=198~\\text{cm}^2 \\\\\n\\mathcal{A} &amp;= 330~\\text{cm}^2+198~\\text{cm}^2=528~\\text{cm}^2\n\\end{aligned}\\] ដូច្នេះផ្ទៃក្រឡា \\(\\mathcal{A}=528~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ចំណោទ</p><h2>ប្រតិបត្តិ</h2><p>គណនាផ្ទៃក្រឡាតាមរូបខាងក្រោម ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ចំណោទ</p><h2>ចម្លើយ</h2><p>ចែករូបជាចតុកោណកែងពីរ ៖ ចតុកោណកែងឈរ \\(14~\\text{cm}\\times32~\\text{cm}\\) និងចតុកោណកែងដេកខាងស្តាំ \\((37-14)~\\text{cm}\\times18~\\text{cm}\\) ៖ \\[\\begin{aligned}\n\\mathcal{A}_1 &amp;= 14\\times32=448~\\text{cm}^2 \\\\\n\\mathcal{A}_2 &amp;= (37-14)\\times18=23\\times18=414~\\text{cm}^2 \\\\\n\\mathcal{A} &amp;= 448+414=862~\\text{cm}^2\n\\end{aligned}\\] ដូចនេះ \\(862~\\text{cm}^2\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៦</p><h1>លំហាត់</h1><p class=\"ts-sub\">បរិមាត្រនិងផ្ទៃក្រឡាពហុកោណ</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១</h2><p>សង់ចតុកោណកែងមួយដោយស្គាល់រង្វាស់វិមាត្រទាំងពីរ \\(20~\\text{cm}\\) និង \\(14~\\text{cm}\\) ។ គណនាបរិមាត្រនិងផ្ទៃក្រឡាចតុកោណនោះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១</h2><p>\\[\\begin{aligned}\n    P &amp;= 2(20+14)=2\\times34=68~\\text{cm} \\\\\n    \\mathcal{A} &amp;= 20\\times14=280~\\text{cm}^2\n    \\end{aligned}\\] ដូចនេះ \\(P=68~\\text{cm}\\) និង \\(\\mathcal{A}=280~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ២</h2><p>សង់ការ៉េមួយដោយស្គាល់បរិមាត្រ \\(120~\\text{mm}\\) ។ គណនាជ្រុងនិងផ្ទៃក្រឡាការ៉េនោះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២</h2><p>\\[\\begin{aligned}\n    a &amp;= \\frac{P}{4}=\\frac{120}{4}=30~\\text{mm} \\\\\n    \\mathcal{A} &amp;= a^2=30^2=900~\\text{mm}^2\n    \\end{aligned}\\] ដូចនេះ ជ្រុង \\(30~\\text{mm}\\) និងផ្ទៃក្រឡា \\(900~\\text{mm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៣</h2><p>រកកម្ពស់ត្រីកោណមួយដោយស្គាល់ផ្ទៃក្រឡា \\(49~\\text{cm}^2\\) និងបាតស្មើ \\(12~\\text{cm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣</h2><p>\\[\\begin{aligned}\n    \\mathcal{A} &amp;= \\frac{1}{2}b\\times h \\\\\n    h &amp;= \\frac{2\\mathcal{A}}{b}=\\frac{2\\times49}{12} \\\\\n     &amp;= \\frac{49}{6}\\approx8.17~\\text{cm}\n    \\end{aligned}\\] ដូចនេះ កម្ពស់ \\(h=\\dfrac{49}{6}\\approx8.17~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៤</h2><p>គណនាផ្ទៃក្រឡាការ៉េតូចនៅក្នុងការ៉េធំ (រូបខាងក្រោម) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤</h2><p>ការ៉េធំមានជ្រុង \\(45~\\text{cm}\\) ។ ត្រីកោណកែងបួនស្មើគ្នានៅជ្រុងទាំងបួន មានជ្រុងកែង \\(15~\\text{cm}\\) និង \\(45-15=30~\\text{cm}\\) ។ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{ការ៉េធំ}} &amp;= 45^2=2~025~\\text{cm}^2 \\\\\n    \\mathcal{A}_{\\text{ត្រីកោណមួយ}} &amp;= \\frac{1}{2}\\times15\\times30=225~\\text{cm}^2 \\\\\n    \\mathcal{A}_{\\text{ការ៉េតូច}} &amp;= 2~025-4\\times225 \\\\\n     &amp;= 2~025-900 \\\\\n     &amp;= 1~125~\\text{cm}^2\n    \\end{aligned}\\] ដូចនេះ ផ្ទៃក្រឡាការ៉េតូចស្មើ \\(1~125~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៥</h2><p>រកផ្ទៃក្រឡាផ្នែកពណ៌នៃរូបខាងក្រោម ។ (ឯកតាគិតជា \\(\\text{m}\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">រូបទី 1.</span><div>ចតុកោណកែងធំ \\(15\\times9\\) ។ ផ្នែកខាងស្តាំមានការ៉េស \\(3\\times3\\) នៅផ្នែកក្រោម ។ ផ្នែកពណ៌ក្នុងជួរខាងលើ (កម្ពស់ \\(9-3=6\\)) ទទឹង \\(2\\) ហើយក្នុងជួរខាងក្រោម (កម្ពស់ \\(3\\)) ទទឹង \\(15-3=12\\) ៖ \\[\\begin{aligned}\n        \\mathcal{A} &amp;= 2\\times6+12\\times3 \\\\\n         &amp;= 12+36 \\\\\n         &amp;= 48~\\text{m}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">រូបទី 2.</span><div>ត្រីកោណពណ៌មានបាត \\(8\\) និងកម្ពស់ \\(4\\) ៖ \\[\\mathcal{A}=\\frac{1}{2}\\times8\\times4=16~\\text{m}^2\\]</div></li><li class=\"lab\"><span class=\"lb\">រូបទី 3.</span><div>ចតុកោណកែងធំមានទទឹង \\(2+3=5\\) និងកម្ពស់ \\(1+3=4\\) ។ ដកផ្នែកស ៖ ចតុកោណកែងស្តើង \\(1\\times3\\) និងចតុកោណកែងខាងលើស្តាំ \\(3\\times2\\) ៖ \\[\\begin{aligned}\n        \\mathcal{A} &amp;= 5\\times4-1\\times3-3\\times2 \\\\\n         &amp;= 20-3-6 \\\\\n         &amp;= 11~\\text{m}^2\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៦</h2><p>តាមមាត្រដ្ឋាន \\(\\dfrac{1}{200}\\) ផែនទីសួនមួយរាងការ៉េមានរង្វាស់ជ្រុង \\(7.9~\\text{dm}\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាផ្ទៃក្រឡាសួននោះនៅលើផែនទីគិតជា \\(\\text{dm}^2\\) ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើផ្ទៃក្រឡាសួនពិតនៅលើផ្ទៃដីមានប៉ុន្មានអា ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\mathcal{A}_{\\text{ផែនទី}}=7.9^2=62.41~\\text{dm}^2\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ជ្រុងពិត \\(=200\\times7.9~\\text{dm}=1~580~\\text{dm}=158~\\text{m}\\) ៖ \\[\\begin{aligned}\n        \\mathcal{A}_{\\text{ពិត}} &amp;= 158^2=24~964~\\text{m}^2 \\\\\n         &amp;= 249.64~\\text{a}\n        \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ក. \\(62.41~\\text{dm}^2\\) ខ. \\(249.64~\\text{a}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៧</h2><p>ផ្ទៃការ៉េប្រាំខាងក្រោមផ្តុំបានជាការ៉េមួយ ។ រកផ្ទៃក្រឡារបស់ការ៉េនោះ បើគេយកមួយការ៉ូឯកតាស្មើនឹង \\(1~\\text{ca}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៧</h2><p>រាប់ការ៉ូនៃផ្នែកនីមួយៗ ៖ \\(4+5+8+3+5=25\\) ការ៉ូ ។ \\[25\\times1~\\text{ca}=25~\\text{ca}\\] ការ៉េដែលផ្តុំបានមានជ្រុង \\(5\\) ការ៉ូ (\\(5\\times5=25\\)) ។ ដូចនេះ ផ្ទៃក្រឡាការ៉េនោះស្មើ \\(25~\\text{ca}\\) \\((=25~\\text{m}^2)\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៨</h2><p>ចម្ការចតុកោណកែងមួយមានបរិមាត្រ \\(500~\\text{m}\\) ហើយទទឹងមានប្រវែង \\(\\dfrac{1}{4}\\) នៃបណ្តោយ ។ រកផ្ទៃក្រឡាចម្ការនោះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៨</h2><p>តាង \\(b\\) ជាបណ្តោយ នោះទទឹង \\(a=\\dfrac{b}{4}\\) ។ កន្លះបរិមាត្រ \\(a+b=\\dfrac{500}{2}=250\\) ៖ \\[\\begin{aligned}\n    \\frac{b}{4}+b &amp;= 250 \\\\\n    \\frac{5b}{4} &amp;= 250 \\\\\n    b &amp;= 250\\times\\frac{4}{5}=200~\\text{m}\n    \\end{aligned}\\] \\[a=\\frac{200}{4}=50~\\text{m}\\] \\[\\mathcal{A}=200\\times50=10~000~\\text{m}^2\\] ដូចនេះ ផ្ទៃក្រឡាចម្ការ \\(10~000~\\text{m}^2\\) (\\(=1~\\text{ha}\\)) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៩</h2><p>ដីស្រែមួយកន្លែងរាងត្រីកោណមានបាត \\(258~\\text{m}\\) និងកម្ពស់មានប្រវែង \\(\\dfrac{2}{3}\\) នៃបាត ។ នៅក្នុងស្រែនោះគេជីកស្រះរាងចតុកោណកែងមានទទឹង \\(13~\\text{m}\\) និងបណ្តោយស្មើ \\(\\dfrac{1}{3}\\) នៃកម្ពស់ត្រីកោណ ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>រកផ្ទៃក្រឡាស្រះ ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រកផ្ទៃក្រឡាដីស្រែដែលនៅសល់ពីជីកស្រះ ។</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>រកផលស្រូវទាំងអស់ បើក្នុងមួយហិកតាទទួលផលបាន \\(3\\) តោន ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៩</h2><p>កម្ពស់ត្រីកោណ \\(=\\dfrac{2}{3}\\times258=172~\\text{m}\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បណ្តោយស្រះ \\(=\\dfrac{172}{3}~\\text{m}\\) ៖ \\[\\begin{aligned}\n        \\mathcal{A}_{\\text{ស្រះ}} &amp;= 13\\times\\frac{172}{3} \\\\\n         &amp;= \\frac{2~236}{3}\\approx745.33~\\text{m}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ផ្ទៃក្រឡាដីស្រែទាំងមូល ៖ \\[\\mathcal{A}_{\\text{ស្រែ}}=\\frac{1}{2}\\times258\\times172=22~188~\\text{m}^2\\] \\[\\begin{aligned}\n        \\mathcal{A}_{\\text{នៅសល់}} &amp;= 22~188-\\frac{2~236}{3} \\\\\n         &amp;= \\frac{64~328}{3}\\approx21~442.67~\\text{m}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ប្តូរជាហិកតា ៖ \\(21~442.67~\\text{m}^2\\approx2.1443~\\text{ha}\\) ។ \\[\\begin{aligned}\n        \\text{ផលស្រូវ} &amp;= 2.1443\\times3 \\\\\n         &amp;\\approx6.43~\\text{តោន}\n        \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ក. \\(\\approx745.33~\\text{m}^2\\) ខ. \\(\\approx21~442.67~\\text{m}^2\\) គ. \\(\\approx6.43\\) តោន ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៦</p><h1>ចប់មេរៀន</h1><p class=\"ts-sub\">បរិមាត្រនិងផ្ទៃក្រឡាពហុកោណ</p>"}];
